	t, err := s.GetTask(ctx, id)
	if err != nil {
		return TaskDetail{}, err
	}
	var owner *Actor
	if t.OwnerID != "" {
		owner, _ = s.GetActor(ctx, t.OwnerID)
	}
	c, _ := s.ListContext(ctx, id)
	decisions, _ := s.ListDecisions(ctx, id)
	comments, _ := s.ListComments(ctx, id)
	artifacts, _ := s.ListArtifacts(ctx, id)
	gitRefs, _ := s.ListGitRefs(ctx, id)
	l, _ := s.ListLocks(ctx, id, false)
	h, _ := s.ListHandoffs(ctx, id)
	snapshots, _ := s.ListContextSnapshots(ctx, id)
	packet, _ := s.LatestHandoffPacket(ctx, id)
	checkpoints, _ := s.ListHandoffCheckpoints(ctx, id)
	e, _ := s.ListEvents(ctx, 0, id)
	subtasks, _ := s.ListSubtasks(ctx, id)
	dependencies, _ := s.ListTaskDependencies(ctx, id)
	dependents, _ := s.ListTaskDependents(ctx, id)
	var parent *Task
	if t.ParentTaskID != "" {
		if p, err := s.GetTask(ctx, t.ParentTaskID); err == nil {
			parent = &p
		}
	}
	var latestSnapshot *ContextSnapshot
	if len(snapshots) > 0 {
		latestSnapshot = &snapshots[len(snapshots)-1]
	}
	detail := TaskDetail{Task: t, Owner: owner, Parent: parent, Subtasks: subtasks, Dependencies: dependencies, Dependents: dependents, Context: c, Decisions: decisions, Comments: comments, Artifacts: artifacts, GitRefs: gitRefs, Locks: l, Handoffs: h, Snapshots: snapshots, LatestSnapshot: latestSnapshot, HandoffPacket: packet, HandoffCheckpoints: checkpoints, Events: e}
	if packet != nil && len(checkpoints) > 0 && packet.Source == "agent_authored" {
		rebuilt := buildHandoffPacketFromCheckpoints(detail, checkpoints)
		rebuiltPacket := *packet
		rebuiltPacket.Packet = rebuilt
		rebuiltPacket.Markdown = renderHandoffMarkdown(rebuilt)
		rebuiltPacket.ValidationErrors = validateHandoffQuality(rebuilt)
		detail.HandoffPacket = &rebuiltPacket
	}
	return detail, nil
}

